parameters.jsCode:
// WF-03 · Puntuación y veredicto.
//
// El cerebro del SOAR y la parte con más capacidad de causar daño. Los pesos
// viven en scoring/weights.json, versionados aparte, y todo veredicto emite su
// `rationale`: un analista debe poder reconstruir por qué el sistema decidió
// aislar un host. Un veredicto sin justificación es incauditable.

// @blinksec-inject: scoring/weights.json
// @blinksec-inject: scoring/score.js

const alerta = $('Entrada desde WF-02').first().json;

// Allowlist propia. Se evalúa DENTRO de score() como puerta 0, antes de
// cualquier aritmética de puntuación.
const allowlist = $input.all()
  .map((i) => i.json.cidr)
  .filter(Boolean);

const resultado = score(alerta, alerta.enrichment, { allowlist });

const ahora = Date.now();

return [
  {
    json: {
      ...alerta,
      triage: resultado,
      timings: {
        ...(alerta.timings ?? {}),
        // Latencia de extremo a extremo: la métrica que importa
        // operativamente, dominada por las APIs de inteligencia. El tiempo de
        // cómputo del flujo es un orden de magnitud menor y se mide aparte
        // para no confundir una cosa con la otra.
        e2eMs: alerta.ingestStartedAt ? ahora - alerta.ingestStartedAt : null,
        triagedAt: ahora,
      },
    },
  },
];

parameters.query:
UPDATE blinksec.alerts
SET score = $2, verdict = $3, partial_enrichment = $4, processed_at = now()
WHERE alert_id = $1;

